import { useMenuStore } from '@/store/app';

export default {
    mounted(el, binding, vnode, prevVnode) {


        const menuStore = useMenuStore();

        const key = binding.value;
        if (!menuStore.buttonList.some(({ id }) => id == key)) {
            el.parentNode && el.parentNode.removeChild(el);
        }
    }
};
